package com.aaliyun.leadnews.search.service;
import co.elastic.clients.elasticsearch.ElasticsearchClient;import co.elastic.clients.elasticsearch._types.SortOrder;import co.elastic.clients.elasticsearch.core.SearchResponse;import co.elastic.clients.elasticsearch.core.search.*;import com.aaliyun.leadnews.common.exception.BusinessException;import com.aaliyun.leadnews.model.search.ArticleSearchDocument;import com.aaliyun.leadnews.search.config.SearchIndexInitializer;import org.springframework.stereotype.Service;import java.util.*;
@Service public class ArticleSearchService{private final ElasticsearchClient client;private final SearchHistoryService history;public ArticleSearchService(ElasticsearchClient c,SearchHistoryService h){client=c;history=h;}
 public SearchPage search(String keyword,Long channelId,int page,int size,String sort){if((long)page*size>10000)throw new BusinessException(40000,"page * size must not exceed 10000");try{SearchResponse<ArticleSearchDocument>r=client.search(s->{s.index(SearchIndexInitializer.ARTICLE_ALIAS).from((page-1)*size).size(size).query(q->q.bool(b->{b.must(m->m.multiMatch(mm->mm.query(keyword).fields("title^3","summary^2","content^1")));if(channelId!=null)b.filter(f->f.term(t->t.field("channelId").value(channelId)));return b;})).highlight(h->h.encoder(HighlighterEncoder.Html).preTags("<em>").postTags("</em>").fields("title",f->f.numberOfFragments(0)).fields("content",f->f.fragmentSize(150).numberOfFragments(2)));if("TIME".equalsIgnoreCase(sort))s.sort(o->o.field(f->f.field("publishTime").order(SortOrder.Desc)));else s.sort(o->o.score(sc->sc.order(SortOrder.Desc))).sort(o->o.field(f->f.field("publishTime").order(SortOrder.Desc)));return s;},ArticleSearchDocument.class);List<SearchItem>items=r.hits().hits().stream().map(this::item).toList();if(page==1)history.remember(keyword);return new SearchPage(r.hits().total()==null?items.size():r.hits().total().value(),page,size,items);}catch(BusinessException e){throw e;}catch(Exception e){throw new BusinessException(50300,"Search engine is temporarily unavailable");}}
 public List<String>suggest(String prefix,int size){try{SearchResponse<Map>r=client.search(s->s.index(SearchIndexInitializer.SUGGEST_ALIAS).size(Math.min(10,size)).query(q->q.matchPhrasePrefix(m->m.field("suggestion").query(prefix))).source(src->src.filter(f->f.includes("title"))),Map.class);return r.hits().hits().stream().map(Hit::source).filter(Objects::nonNull).map(m->String.valueOf(m.get("title"))).distinct().limit(10).toList();}catch(Exception e){throw new BusinessException(50300,"Search engine is temporarily unavailable");}}
 private SearchItem item(Hit<ArticleSearchDocument>d){Map<String,List<String>>h=d.highlight();Double score=Double.isNaN(d.score())?null:d.score();return new SearchItem(d.source(),h.getOrDefault("title",List.of()),h.getOrDefault("content",List.of()),score);}public record SearchItem(ArticleSearchDocument article,List<String>highlightedTitle,List<String>highlightedContent,Double score){}public record SearchPage(long total,int page,int size,List<SearchItem>items){}}
